package httpapi

import (
	"database/sql"
	"errors"
	"net/http"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/google/uuid"
	"github.com/jmoiron/sqlx"
	"github.com/labstack/echo/v4"
)

// maxTitleLength is the longest title, counted in characters.
const maxTitleLength = 200

// Note is a stored note. The db tags map the columns for sqlx. ID is a canonical lowercase
// hyphenated UUID v4 string, generated by the server. Tags is not a column of the notes table, so
// db:"-" keeps sqlx from scanning or binding it; it is loaded separately, sorted ascending, and
// always an empty slice when the note has none, so it marshals as [] and not null.
type Note struct {
	ID        string     `db:"id" json:"id"`
	Title     string     `db:"title" json:"title"`
	Body      string     `db:"body" json:"body"`
	CreatedAt time.Time  `db:"created_at" json:"created_at"`
	Status    NoteStatus `db:"status" json:"status"`
	Tags      []string   `db:"-" json:"tags"`
}

// noteRequest is the title and body a note is written with. It is embedded in createNoteRequest
// and is the whole body PUT /notes/:id accepts, so neither route has a status field there.
type noteRequest struct {
	Title string `json:"title"`
	Body  string `json:"body"`
}

// createNoteRequest is the body accepted when a note is created: the title and body of
// noteRequest plus an optional status. A nil Status, from an absent or null field, means the note
// is created as a draft; any other value has to name one of the three statuses.
type createNoteRequest struct {
	noteRequest
	Status *string `json:"status"`
}

// validate applies the rules a note has: a title that is not blank and at most maxTitleLength
// characters. The body is free text and may be empty.
func (r noteRequest) validate() error {
	title := strings.TrimSpace(r.Title)
	if title == "" {
		return errors.New("title is required")
	}
	if utf8.RuneCountInString(title) > maxTitleLength {
		return errors.New("title must be at most 200 characters")
	}
	return nil
}

// createNote handles POST /notes.
func createNote(db *sqlx.DB) echo.HandlerFunc {
	return func(c echo.Context) error {
		var req createNoteRequest
		if err := c.Bind(&req); err != nil {
			return writeError(c, http.StatusBadRequest, "invalid JSON body")
		}
		if err := req.validate(); err != nil {
			return writeError(c, http.StatusBadRequest, err.Error())
		}

		// A note without a status is a draft; anything else sent has to name a status, and an
		// unknown name creates no note at all.
		status := StatusDraft
		if req.Status != nil {
			parsed, err := parseNoteStatus(*req.Status)
			if err != nil {
				return writeError(c, http.StatusBadRequest, err.Error())
			}
			status = parsed
		}

		note := Note{
			ID:        uuid.New().String(),
			Title:     strings.TrimSpace(req.Title),
			Body:      req.Body,
			CreatedAt: time.Now().UTC(),
			Status:    status,
			Tags:      []string{},
		}
		_, err := db.NamedExecContext(c.Request().Context(),
			"INSERT INTO notes (id, title, body, created_at, status) VALUES (:id, :title, :body, :created_at, :status)", note)
		if err != nil {
			return writeError(c, http.StatusInternalServerError, "creating note")
		}
		return c.JSON(http.StatusCreated, note)
	}
}

// listNotes handles GET /notes: every note in created_at order, narrowed by ?tag=<name> and
// ?status=<name> when either is present, and by both together when they are. The slice is made up
// front so an empty result marshals as [] and not null.
func listNotes(db *sqlx.DB) echo.HandlerFunc {
	return func(c echo.Context) error {
		ctx := c.Request().Context()
		notes := make([]Note, 0)

		// QueryParams()["tag"] rather than QueryParam tells an explicitly empty ?tag= apart from
		// an absent one: only a missing parameter means "any tag".
		var tag *string
		if values, filterByTag := c.QueryParams()["tag"]; filterByTag {
			if !tagPattern.MatchString(values[0]) {
				// A value that cannot be a tag matches nothing: an empty list, not a 400, and no
				// query at all.
				return c.JSON(http.StatusOK, notes)
			}
			tag = &values[0]
		}

		// A status parameter is different: it only exists to name one of the three statuses, so a
		// value that names none of them is a 400 rather than an empty list.
		var status *NoteStatus
		if values, filterByStatus := c.QueryParams()["status"]; filterByStatus {
			parsed, err := parseNoteStatus(values[0])
			if err != nil {
				return writeError(c, http.StatusBadRequest, err.Error())
			}
			status = &parsed
		}

		query, args := notesQuery(tag, status)
		if err := db.SelectContext(ctx, &notes, query, args...); err != nil {
			return writeError(c, http.StatusInternalServerError, "listing notes")
		}

		// One statement for the whole page, whatever its size: the tags of every listed note at
		// once, never one query per note.
		ids := make([]string, 0, len(notes))
		for i := range notes {
			notes[i].Tags = []string{}
			ids = append(ids, notes[i].ID)
		}
		tags, err := loadTags(ctx, db, ids)
		if err != nil {
			return writeError(c, http.StatusInternalServerError, "listing notes")
		}
		for i := range notes {
			if names, ok := tags[notes[i].ID]; ok {
				notes[i].Tags = names
			}
		}
		return c.JSON(http.StatusOK, notes)
	}
}

// notesQuery builds the SELECT behind GET /notes: every note in created_at order, with the rowid
// breaking a tie so the order is deterministic and repeats across requests. Each filter is optional
// and they are combined with AND, so ?tag=go&status=published lists only the notes that carry the
// tag and have that status. Only the tag filter needs the joins, and they cannot list a note twice:
// (note_id, tag_id) is the primary key of note_tags, so a note has at most one link to the tag
// being filtered on.
func notesQuery(tag *string, status *NoteStatus) (string, []any) {
	query := "SELECT n.id, n.title, n.body, n.created_at, n.status FROM notes n"
	conditions := make([]string, 0, 2)
	args := make([]any, 0, 2)

	if tag != nil {
		query += `
   JOIN note_tags nt ON nt.note_id = n.id
   JOIN tags t       ON t.id = nt.tag_id`
		conditions = append(conditions, "t.name = ?")
		args = append(args, *tag)
	}
	if status != nil {
		conditions = append(conditions, "n.status = ?")
		args = append(args, *status)
	}
	if len(conditions) > 0 {
		query += "\n  WHERE " + strings.Join(conditions, "\n    AND ")
	}
	query += "\n  ORDER BY n.created_at, n.rowid"
	return query, args
}

// parseNoteID reads the :id path parameter, accepting only the canonical lowercase hyphenated form
// of a UUID. uuid.Parse on its own also takes uppercase, 32 bare hex characters, braces and the
// urn: form, so the parsed value has to be written back exactly as it came in; anything else is an
// invalid id.
func parseNoteID(c echo.Context) (string, error) {
	raw := c.Param("id")
	id, err := uuid.Parse(raw)
	if err != nil || id.String() != raw {
		return "", errors.New("invalid note id")
	}
	return raw, nil
}

// updateNote handles PUT /notes/:id. The id is checked and the note loaded before the body is
// looked at, so a missing note is a 404 even when the body is invalid too. It is a full
// replacement: an omitted body stores the empty string, while id and created_at are kept.
func updateNote(db *sqlx.DB) echo.HandlerFunc {
	return func(c echo.Context) error {
		id, err := parseNoteID(c)
		if err != nil {
			return writeError(c, http.StatusBadRequest, "invalid note id")
		}

		var note Note
		err = db.GetContext(c.Request().Context(), &note,
			"SELECT id, title, body, created_at, status FROM notes WHERE id = ?", id)
		if errors.Is(err, sql.ErrNoRows) {
			return writeError(c, http.StatusNotFound, "note not found")
		}
		if err != nil {
			return writeError(c, http.StatusInternalServerError, "loading note")
		}

		var req noteRequest
		if err := c.Bind(&req); err != nil {
			return writeError(c, http.StatusBadRequest, "invalid JSON body")
		}
		if err := req.validate(); err != nil {
			return writeError(c, http.StatusBadRequest, err.Error())
		}

		title := strings.TrimSpace(req.Title)
		_, err = db.ExecContext(c.Request().Context(),
			"UPDATE notes SET title = ?, body = ? WHERE id = ?", title, req.Body, id)
		if err != nil {
			return writeError(c, http.StatusInternalServerError, "updating note")
		}
		note.Title = title
		note.Body = req.Body

		// This route replaces title and body only: the note's tags are loaded for the response
		// but never written, so PUT /notes/:id leaves them exactly as they were.
		note.Tags = []string{}
		tags, err := loadTags(c.Request().Context(), db, []string{note.ID})
		if err != nil {
			return writeError(c, http.StatusInternalServerError, "updating note")
		}
		if names, ok := tags[note.ID]; ok {
			note.Tags = names
		}
		return c.JSON(http.StatusOK, note)
	}
}

// putNoteTags handles PUT /notes/:id/tags: it replaces the note's whole tag set with the one in
// the body, and clears it when the body carries no tags. Like updateNote the id is checked and
// the note loaded before the body is looked at, so a missing note is a 404 even when the body is
// invalid too. The replacement is all or nothing: a rejected request stores nothing.
func putNoteTags(db *sqlx.DB) echo.HandlerFunc {
	return func(c echo.Context) error {
		id, err := parseNoteID(c)
		if err != nil {
			return writeError(c, http.StatusBadRequest, "invalid note id")
		}

		var note Note
		err = db.GetContext(c.Request().Context(), &note,
			"SELECT id, title, body, created_at, status FROM notes WHERE id = ?", id)
		if errors.Is(err, sql.ErrNoRows) {
			return writeError(c, http.StatusNotFound, "note not found")
		}
		if err != nil {
			return writeError(c, http.StatusInternalServerError, "loading note")
		}

		var req tagsRequest
		if err := c.Bind(&req); err != nil {
			return writeError(c, http.StatusBadRequest, "invalid JSON body")
		}
		names, err := normalizeTags(req.Tags)
		if err != nil {
			return writeError(c, http.StatusBadRequest, err.Error())
		}

		if err := replaceTags(c.Request().Context(), db, note.ID, names); err != nil {
			return writeError(c, http.StatusInternalServerError, "updating tags")
		}

		// The response carries the set that was just stored, loaded the same way a later GET
		// would load it, so it is sorted ascending and [] rather than null when it is empty.
		note.Tags = []string{}
		tags, err := loadTags(c.Request().Context(), db, []string{note.ID})
		if err != nil {
			return writeError(c, http.StatusInternalServerError, "updating tags")
		}
		if stored, ok := tags[note.ID]; ok {
			note.Tags = stored
		}
		return c.JSON(http.StatusOK, note)
	}
}

// deleteNote handles DELETE /notes/:id: 204 with no body, or 404 when there was nothing to
// delete.
func deleteNote(db *sqlx.DB) echo.HandlerFunc {
	return func(c echo.Context) error {
		id, err := parseNoteID(c)
		if err != nil {
			return writeError(c, http.StatusBadRequest, "invalid note id")
		}

		result, err := db.ExecContext(c.Request().Context(), "DELETE FROM notes WHERE id = ?", id)
		if err != nil {
			return writeError(c, http.StatusInternalServerError, "deleting note")
		}
		affected, err := result.RowsAffected()
		if err != nil {
			return writeError(c, http.StatusInternalServerError, "deleting note")
		}
		if affected == 0 {
			return writeError(c, http.StatusNotFound, "note not found")
		}
		return c.NoContent(http.StatusNoContent)
	}
}

// getNote handles GET /notes/:id. An id that is not a canonical UUID is a 400, a missing note a
// 404.
func getNote(db *sqlx.DB) echo.HandlerFunc {
	return func(c echo.Context) error {
		id, err := parseNoteID(c)
		if err != nil {
			return writeError(c, http.StatusBadRequest, "invalid note id")
		}

		var note Note
		err = db.GetContext(c.Request().Context(), &note,
			"SELECT id, title, body, created_at, status FROM notes WHERE id = ?", id)
		if errors.Is(err, sql.ErrNoRows) {
			return writeError(c, http.StatusNotFound, "note not found")
		}
		if err != nil {
			return writeError(c, http.StatusInternalServerError, "loading note")
		}

		note.Tags = []string{}
		tags, err := loadTags(c.Request().Context(), db, []string{note.ID})
		if err != nil {
			return writeError(c, http.StatusInternalServerError, "loading note")
		}
		if names, ok := tags[note.ID]; ok {
			note.Tags = names
		}
		return c.JSON(http.StatusOK, note)
	}
}
